using Astrea.BattleActions;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "DazzlingLightCustomDescription", menuName = "Data/Battle/Battle Actions/BaseBattleActionData/Austra/DazzlingLightCustomDescription", order = 0)]
public class DazzlingLightCustomDescription : CustomBattleActionDescription
{
	public override string GetActionDescription(string amountModified, BattleAction battleAction)
	{
		DazzlingLightAction dazzlingLightAction = battleAction as DazzlingLightAction;
		string arg = dazzlingLightAction.PurifyAction.GetActionDescription(GetFinalAmountWithoutEquation(amountModified)).RemoveLast();
		string localizedForEach = base.localizationManager.GetLocalizedForEach();
		string rawLocalizedDescription = GetRawLocalizedDescription(battleAction);
		if (LanguagesIndexes.IsCurrentLanguageSimplifiedChinese())
		{
			return dazzlingLightAction.SecondPurifyAction.GetActionDescription(GetAmountWithoutEquation(amountModified), GetBonusAmountWithoutEquation(amountModified)) + "\n" + Smart.Format(rawLocalizedDescription, Smart.Format(localizedForEach.Replace(" {1}", "").Replace("{1}", ""), arg));
		}
		return dazzlingLightAction.SecondPurifyAction.GetActionDescription(GetAmountWithoutEquation(amountModified), GetBonusAmountWithoutEquation(amountModified)) + "\n" + Smart.Format(base.localizationManager.GetLocalizedInYourHand(removeDotIfJapaneseOrTraditionalChinese: false), Smart.Format(rawLocalizedDescription, Smart.Format(localizedForEach.Replace(" {1}", "").Replace("{1}", ""), arg)));
	}
}
